namespace eh=electrode_heat_v2;
namespace fs=std::filesystem;
void require(bool q,const std::string& message){if(!q)throw std::runtime_error(message);}
struct Sigma:Coefficient {const eh::Coupler& upper;const eh::Coupler& lower;int selected=-1;Sigma(const eh::Coupler&a,const eh::Coupler&b,int s=-1):upper(a),lower(b),selected(s){}real_t Eval(ElementTransformation&tr,const IntegrationPoint&ip)override{int body=tr.Attribute==2?0:tr.Attribute==3?1:-1;if(body<0||(selected>=0&&body!=selected))return 0;Vector x(2);tr.Transform(ip,x);return (body==0?upper:lower).electrical_conductivity_at(x[0],x[1]);}};
struct OnlineEM:EMGrid {Sigma sigma;OnlineEM(Settings&s,const eh::Coupler&a,const eh::Coupler&b):EMGrid(s),sigma(a,b){}void Reassemble(){const auto& rule=IntRules.Get(Geometry::SQUARE,6);mass=std::make_unique<BilinearForm>(space.get());auto* integ=new MassIntegrator(sigma);integ->SetIntRule(&rule);mass->AddDomainIntegrator(integ);mass->Assemble();mass->Finalize();for(int body=0;body<2;++body){Sigma selected(sigma.upper,sigma.lower,body);LinearForm form(space.get());auto* lf=new DomainLFIntegrator(selected,6);lf->SetIntRule(&rule);form.AddDomainIntegrator(lf);form.Assemble();f[body]=form;d[body]=form.Sum();require(d[body]>0,"nonpositive current constraint conductivity");}}};
struct Joule:Coefficient {OnlineEM& em;const eh::Coupler& heat;double gradient;Joule(OnlineEM&e,const eh::Coupler&h,double g):em(e),heat(h),gradient(g){}real_t Eval(ElementTransformation&tr,const IntegrationPoint&ip)override{Vector x(2);tr.Transform(ip,x);double E=gradient-em.RateAt(x[0],x[1]);return heat.electrical_conductivity_at(x[0],x[1])*E*E;}};
struct FieldResult {double gradient[2]{},current[2]{},power=0,work=0,damping=0,magnetic=0,residual=0,linear_residual=0,sigma_min=INFINITY,sigma_max=0;int iterations=0;};
FieldResult field_step(OnlineEM&em,double dt,double I){em.Reassemble();Vector old(*em.potential),rhs(old.Size()),base,q0,q1;auto matrix=em.Matrix(1/dt);LinearSystem solver(*matrix);em.mass->Mult(old,rhs);rhs/=dt;em.ZeroBoundary(rhs);solver.Solve(rhs,base);solver.Solve(em.f[0],q0);solver.Solve(em.f[1],q1);Vector delta(base);delta-=old;double c00=em.d[0]-(em.f[0]*q0)/dt,c01=-(em.f[0]*q1)/dt,c10=-(em.f[1]*q0)/dt,c11=em.d[1]-(em.f[1]*q1)/dt;double r0=I+(em.f[0]*delta)/dt,r1=-I+(em.f[1]*delta)/dt,det=c00*c11-c01*c10;require(c00>0&&c11>0&&det>0,"indefinite current Schur complement");FieldResult r;r.gradient[0]=(r0*c11-c01*r1)/det;r.gradient[1]=(c00*r1-c10*r0)/det;double old_magnetic=em.MagneticEnergy();*em.potential=base;em.potential->Add(r.gradient[0],q0);em.potential->Add(r.gradient[1],q1);*em.rate=*em.potential;*em.rate-=old;*em.rate/=dt;Vector change(*em.potential);change-=old;Vector kc(change.Size());em.stiffness->Mult(change,kc);r.damping=.5*(change*kc)*em.s.length;r.work=dt*em.s.length*I*(r.gradient[0]-r.gradient[1]);r.magnetic=em.MagneticEnergy();
 const auto&rule=IntRules.Get(Geometry::SQUARE,6);for(int e=0;e<em.mesh->GetNE();++e){auto* tr=em.mesh->GetElementTransformation(e);int body=tr->Attribute==2?0:tr->Attribute==3?1:-1;if(body<0)continue;for(int q=0;q<rule.GetNPoints();++q){auto&ip=rule.IntPoint(q);tr->SetIntPoint(&ip);double sig=em.sigma.Eval(*tr,ip),E=r.gradient[body]-em.rate->GetValue(e,ip),weight=ip.weight*tr->Weight();r.current[body]+=weight*sig*E;r.power+=weight*sig*E*E*em.s.length;r.sigma_min=std::min(r.sigma_min,sig);r.sigma_max=std::max(r.sigma_max,sig);}}
 r.residual=r.work-(r.magnetic-old_magnetic)-dt*r.power-r.damping;r.iterations=solver.iterations;r.linear_residual=solver.residual;require(std::abs(r.current[0]-I)<=std::max(1e-3,1e-8*std::abs(I))&&std::abs(r.current[1]+I)<=std::max(1e-3,1e-8*std::abs(I)),"original current reconstruction guard failed");double bound=1e-8*(std::abs(r.work)+std::abs(r.magnetic-old_magnetic)+dt*r.power+std::abs(r.damping))+512*eh::eps*std::max(r.magnetic,old_magnetic);require(std::abs(r.residual)<=bound,"MQS electromagnetic energy guard failed");return r;}
eh::Geometry heat_geometry(const Settings&s,int body){eh::Geometry g;g.nx=s.nx;g.ny=s.ny;g.x0=-s.width/2;g.y0=body==0?s.gap/2:-s.gap/2-s.thickness;g.width=s.width;g.thickness=s.thickness;g.height=s.length;g.revision="fixed-twofoil-pilot-v1";g.electrode=body==0?"upper":"lower";return g;}
struct ThermalMetrics {double minT=INFINITY,maxT=0,energy=0,headroom=0,min_local_hot_J=INFINITY,max_liquid=0;int max_phase=0;};
ThermalMetrics thermal_metrics(const eh::Coupler&c,const eh::Material&m){ThermalMetrics r;r.energy=c.stored_energy_J();const auto& g=c.geometry();const auto* sp=c.temperature_field().FESpace();const auto* mesh=sp->GetMesh();for(int v=0;v<mesh->GetNV();++v){auto*x=mesh->GetVertex(v);Array<int>d;sp->GetVertexDofs(v,d);double T=c.state().T[d[0]],dx=g.width/g.nx,dy=g.thickness/g.ny;double wx=(x[0]==g.x0||x[0]==g.x0+g.width)?.5:1.,wy=(x[1]==g.y0||x[1]==g.y0+g.thickness)?.5:1.;double vol=dx*dy*wx*wy*g.height,hot=vol*m.delta_h(m.knots.back().T,T);r.headroom+=hot;r.min_local_hot_J=std::min(r.min_local_hot_J,hot);r.minT=std::min(r.minT,T);r.maxT=std::max(r.maxT,T);r.max_phase=std::max(r.max_phase,m.phase_at(T));r.max_liquid=std::max(r.max_liquid,m.liquid_fraction(T));}return r;}
// A rejected-step diagnostic only: solve monotone caloric/conductive equations
// with active domain bounds, then report unbalanced joules on those bounds.
// This state is NEVER committed or reported as a continued physical trajectory.
struct Certificate{double hot_J=0,cold_J=0,interior_residual_J=0,global_residual_J=0,load_J=0,delta_J=0;std::vector<double>T,residual;int iterations=0;};
Certificate rejected_certificate(const eh::Coupler&c,const eh::Material&m,Coefficient&q,double dt){const auto&g=c.geometry();auto* sp=const_cast<FiniteElementSpace*>(c.temperature_field().FESpace());auto*mesh=sp->GetMesh();int n=sp->GetVSize();std::vector<double>xs,ys;for(int v=0;v<mesh->GetNV();++v){auto*x=mesh->GetVertex(v);xs.push_back(x[0]);ys.push_back(x[1]);}for(auto*p:{&xs,&ys}){std::sort(p->begin(),p->end());p->erase(std::unique(p->begin(),p->end()),p->end());}std::vector<int> node((g.nx+1)*(g.ny+1));std::vector<double> vol(n),gx(g.nx+1),gy(g.ny+1);for(int i=0;i<=g.nx;++i)gx[i]=.5*((i?xs[i]-xs[i-1]:0)+(i<g.nx?xs[i+1]-xs[i]:0));for(int j=0;j<=g.ny;++j)gy[j]=.5*((j?ys[j]-ys[j-1]:0)+(j<g.ny?ys[j+1]-ys[j]:0));for(int v=0;v<mesh->GetNV();++v){auto*x=mesh->GetVertex(v);int i=std::lower_bound(xs.begin(),xs.end(),x[0])-xs.begin(),j=std::lower_bound(ys.begin(),ys.end(),x[1])-ys.begin();Array<int>d;sp->GetVertexDofs(v,d);node[j*(g.nx+1)+i]=d[0];vol[d[0]]=gx[i]*gy[j]*g.height;}
 std::vector<std::vector<std::pair<int,double>>> adj(n);const auto& old=c.state().T;auto edge=[&](int a,int b,double factor){double ka=m.conductivity(old[a]),kb=m.conductivity(old[b]);double G=(ka==0||kb==0)?0:2*ka*kb/(ka+kb)*factor*g.height;adj[a].push_back({b,G});adj[b].push_back({a,G});};for(int j=0;j<=g.ny;++j)for(int i=0;i<g.nx;++i)edge(node[j*(g.nx+1)+i],node[j*(g.nx+1)+i+1],gy[j]/(xs[i+1]-xs[i]));for(int j=0;j<g.ny;++j)for(int i=0;i<=g.nx;++i)edge(node[j*(g.nx+1)+i],node[(j+1)*(g.nx+1)+i],gx[i]/(ys[j+1]-ys[j]));LinearForm load(sp);load.AddDomainIntegrator(new DomainLFIntegrator(q,6));load.Assemble();Certificate r;r.T=old;r.residual.resize(n);r.load_J=load.Sum()*g.height*dt;double lo=m.knots.front().T,hi=m.knots.back().T;
 for(int iter=0;iter<100;++iter){r.iterations=iter+1;double change=0;for(int i=0;i<n;++i){double conduct=0,neighbor=0;for(auto[j,G]:adj[i]){conduct+=G;neighbor+=G*r.T[j];}double rhs=load[i]*g.height*dt+dt*neighbor;auto F=[&](double T){return vol[i]*m.delta_h(T,old[i])+dt*conduct*T-rhs;};double T=0;if(F(lo)>=0)T=lo;else if(F(hi)<=0)T=hi;else{double a=lo,b=hi;for(int k=0;k<56;++k){double mid=a+.5*(b-a);if(F(mid)>0)b=mid;else a=mid;}T=a+.5*(b-a);}change=std::max(change,std::abs(T-r.T[i]));r.T[i]=T;}if(change<1e-9)break;require(iter<99,"rejected-step energy certificate did not converge");}
 for(int i=0;i<n;++i){double residual=vol[i]*m.delta_h(r.T[i],old[i])-load[i]*g.height*dt;for(auto[j,G]:adj[i])residual+=dt*G*(r.T[i]-r.T[j]);r.residual[i]=residual;r.delta_J+=vol[i]*m.delta_h(r.T[i],old[i]);r.global_residual_J+=residual;if(r.T[i]==hi&&residual<0)r.hot_J-=residual;else if(r.T[i]==lo&&residual>0)r.cold_J+=residual;else r.interior_residual_J+=std::abs(residual);}double bound=512*eh::eps*(std::abs(r.delta_J)+std::abs(r.load_J)+g.width*g.thickness*g.height*m.cv(hi)*hi);require(r.interior_residual_J<=bound,"rejected certificate interior residual too large");require(std::abs(r.delta_J-r.load_J+r.hot_J-r.cold_J)<=bound,"rejected certificate energy does not close");return r;}
std::string header="step,time_s,current_A,upper_current_A,lower_current_A,predicted_loop_voltage_V,min_T_K,max_T_K,max_phase,max_liquid_fraction,thermal_energy_J,hot_headroom_J,min_node_hot_headroom_J,magnetic_energy_J,joule_increment_J,terminal_work_increment_J,BE_magnetic_damping_J,EM_residual_J,thermal_residual_J,joule_mapping_error_J,cumulative_work_J,cumulative_joule_J,cumulative_damping_J,sigma_min_S_m,sigma_max_S_m,linear_relative_residual,linear_iterations";
struct Totals{double work=0,joule=0,damping=0,initial_B=0,initial_H=0;};
std::string stem(int step){std::ostringstream s;s<<"step_"<<std::setw(6)<<std::setfill('0')<<step;return s.str();}
void fields_write(const fs::path&p,const OnlineEM&em,const Totals&t){std::ofstream f(p,std::ios::binary);auto put=[&](const auto&x){f.write(reinterpret_cast<const char*>(&x),sizeof(x));};put(std::uint64_t(0x534f4c4944463031ULL));put(std::uint64_t(em.potential->Size()));for(auto* g:{em.potential.get(),em.rate.get()})for(int i=0;i<g->Size();++i)put((*g)[i]);for(double x:{t.work,t.joule,t.damping,t.initial_B,t.initial_H})put(x);require(bool(f),"field checkpoint failed");}
void fields_read(const fs::path&p,OnlineEM&em,Totals&t){std::ifstream f(p,std::ios::binary);auto get=[&](auto&x){f.read(reinterpret_cast<char*>(&x),sizeof(x));};std::uint64_t magic=0,n=0;get(magic);get(n);require(magic==0x534f4c4944463031ULL&&n==std::uint64_t(em.potential->Size()),"field checkpoint shape");for(auto*g:{em.potential.get(),em.rate.get()})for(int i=0;i<g->Size();++i){get((*g)[i]);require(std::isfinite((*g)[i]),"nonfinite restart field");}for(double*x:{&t.work,&t.joule,&t.damping,&t.initial_B,&t.initial_H})get(*x);require(bool(f)&&f.peek()==std::char_traits<char>::eof(),"field checkpoint truncated/trailing");}
void save(const fs::path&out,int step,const eh::Coupler&a,const eh::Coupler&b,const OnlineEM&em,const Totals&t,const std::string&row){auto p=out/"checkpoints"/stem(step);fs::create_directories(p);a.save((p/"upper.bin").string());b.save((p/"lower.bin").string());fields_write(p/"fields.bin",em,t);std::ofstream f(p/"row.csv");f<<row<<'\n';f.close();std::ofstream marker(out/"CURRENT.tmp");marker<<step<<'\n';marker.close();fs::rename(out/"CURRENT.tmp",out/"CURRENT");}
std::string row(int step,double time,double I,const FieldResult&r,const ThermalMetrics&a,const ThermalMetrics&b,const Totals&t,double q,double th_res,double mismatch){std::ostringstream s;s<<std::setprecision(17)<<step<<','<<time<<','<<I<<','<<r.current[0]<<','<<r.current[1]<<','<<(r.gradient[0]-r.gradient[1])*.025<<','<<std::min(a.minT,b.minT)<<','<<std::max(a.maxT,b.maxT)<<','<<std::max(a.max_phase,b.max_phase)<<','<<std::max(a.max_liquid,b.max_liquid)<<','<<a.energy+b.energy<<','<<a.headroom+b.headroom<<','<<std::min(a.min_local_hot_J,b.min_local_hot_J)<<','<<r.magnetic<<','<<q<<','<<r.work<<','<<r.damping<<','<<r.residual<<','<<th_res<<','<<mismatch<<','<<t.work<<','<<t.joule<<','<<t.damping<<','<<r.sigma_min<<','<<r.sigma_max<<','<<r.linear_residual<<','<<r.iterations;return s.str();}
int main(int argc,char**argv){Mpi::Init(argc,argv);Hypre::Init();try{require(argc==8,"OUTPUT NX NY OUTSIDE GAP MAX_DT_S MAX_STEPS required");cpu_set_t affinity;CPU_ZERO(&affinity);sched_getaffinity(0,sizeof(affinity),&affinity);require(CPU_COUNT(&affinity)==1&&CPU_ISSET(7,&affinity)&&getpriority(PRIO_PROCESS,0)==15&&Mpi::WorldSize()==1,"CPU7/nice15/single-rank required");fs::path out=argv[1];fs::create_directories(out);Settings s;s.nx=std::stoi(argv[2]);s.ny=std::stoi(argv[3]);s.outside=std::stoi(argv[4]);s.gap_cells=std::stoi(argv[5]);s.extent=.04;s.length=.025;double max_dt=std::stod(argv[6]);int max_steps=std::stoi(argv[7]);require(max_dt>0&&max_dt<=2.5e-10&&max_steps>0&&max_steps<=8,"bounded pilot interval/chunk only");std::ifstream schedule(PILOT_SCHEDULE);std::string line;std::getline(schedule,line);std::vector<double> input_t,input_I,times,currents;while(std::getline(schedule,line)){auto i=line.find(',');require(i!=std::string::npos,"schedule row");input_t.push_back(std::stod(line.substr(0,i)));input_I.push_back(std::stod(line.substr(i+1)));}require(input_t.size()>1&&input_t.back()==6e-8,"bounded C19 schedule support");times.push_back(input_t[0]);currents.push_back(input_I[0]);for(std::size_t i=1;i<input_t.size();++i){require(input_t[i]>input_t[i-1],"unordered C19");int n=std::max(1,int(std::ceil((input_t[i]-input_t[i-1])/max_dt)));for(int j=1;j<=n;++j){double f=double(j)/n;times.push_back(j==n?input_t[i]:input_t[i-1]+f*(input_t[i]-input_t[i-1]));currents.push_back(j==n?input_I[i]:input_I[i-1]+f*(input_I[i]-input_I[i-1]));}}
 auto material=eh::conditional_ss304_v2(ss304v2::Qualification::source_conditioned_liquid_3000,ss304::DensityConvention::fixed_reference_volume_cp_as_cv_approximation,8000,eh::material_headers_sha256);std::string source="solid-only-C19-no-particle-sources/v1";eh::Coupler upper(heat_geometry(s,0),material,{},300,source,times[0]),lower(heat_geometry(s,1),material,{},300,source,times[0]);s.sigma=material.sigma(300);OnlineEM em(s,upper,lower);Totals totals;int step=0;distributed_linear::output="";if(fs::exists(out/"CURRENT")){std::ifstream f(out/"CURRENT");f>>step;require(step>=0&&step<int(times.size()),"restart step");auto p=out/"checkpoints"/stem(step);upper.load((p/"upper.bin").string());lower.load((p/"lower.bin").string());fields_read(p/"fields.bin",em,totals);require(upper.state().revision==std::uint64_t(step)&&lower.state().revision==std::uint64_t(step)&&upper.state().time==times[step]&&lower.state().time==times[step],"heat/field clock mismatch");}else{em.Reassemble();em.InitialDC(currents[0]);totals.initial_B=em.MagneticEnergy();totals.initial_H=upper.stored_energy_J()+lower.stored_energy_J();FieldResult init;init.current[0]=currents[0];init.current[1]=-currents[0];init.gradient[0]=currents[0]/em.d[0];init.gradient[1]=-currents[0]/em.d[1];init.magnetic=totals.initial_B;init.sigma_min=init.sigma_max=material.sigma(300);save(out,0,upper,lower,em,totals,row(0,times[0],currents[0],init,thermal_metrics(upper,material),thermal_metrics(lower,material),totals,0,0,0));}
 const auto start=std::chrono::steady_clock::now();int taken=0;while(step+1<int(times.size())&&taken<max_steps&&std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<15){int next=step+1;double dt=times[next]-times[step];Vector old_A(*em.potential),old_rate(*em.rate);auto result=field_step(em,dt,currents[next]);Joule qa(em,upper,result.gradient[0]),qb(em,lower,result.gradient[1]);eh::Trial ta,tb;try{ta=upper.prepare(upper.make_epoch(dt,"same-candidate-MQS-field"),qa,{},{});tb=lower.prepare(lower.make_epoch(dt,"same-candidate-MQS-field"),qb,{},{});}catch(const std::exception&e){auto ca=rejected_certificate(upper,material,qa,dt),cb=rejected_certificate(lower,material,qb,dt);double hot=ca.hot_J+cb.hot_J,cold=ca.cold_J+cb.cold_J;fs::path p=out/"rejected";fs::create_directories(p);fields_write(p/"candidate-fields.bin",em,totals);std::ofstream cells(p/"bound-residual-certificate.csv");cells<<std::setprecision(17)<<"body,node,bound_diagnostic_T_K,residual_J\n";for(int body=0;body<2;++body){const auto&c=body==0?ca:cb;for(std::size_t i=0;i<c.T.size();++i)cells<<body<<','<<i<<','<<c.T[i]<<','<<c.residual[i]<<'\n';}*em.potential=old_A;*em.rate=old_rate;std::ofstream stop(out/"STOP.json");stop<<std::setprecision(17)<<"{\"status\":\"rejected_step_preserved_accepted_state\",\"last_accepted_step\":"<<step<<",\"last_accepted_time_s\":"<<times[step]<<",\"attempted_time_s\":"<<times[next]<<",\"attempted_dt_s\":"<<dt<<",\"attempted_current_A\":"<<currents[next]<<",\"reason\":"<<std::quoted(e.what())<<",\"unsupported_hot_J\":"<<hot<<",\"unsupported_cold_J\":"<<cold<<",\"certificate_interior_residual_J\":"<<ca.interior_residual_J+cb.interior_residual_J<<",\"candidate_Joule_J\":"<<ca.load_J+cb.load_J<<",\"candidate_upper_gradient_V_m\":"<<result.gradient[0]<<",\"candidate_lower_gradient_V_m\":"<<result.gradient[1]<<",\"candidate_terminal_work_J\":"<<result.work<<",\"candidate_EM_residual_J\":"<<result.residual<<",\"certificate_thermal_delta_J\":"<<ca.delta_J+cb.delta_J<<",\"certificate_identity_residual_J\":"<<ca.delta_J+cb.delta_J-ca.load_J-cb.load_J+hot-cold<<",\"diagnostic_bound_state_accepted\":false,\"full_plasma_run\":false}\n";std::cout<<"rejected at "<<times[next]*1e9<<"ns unsupported_hot_J="<<hot<<" reason="<<e.what()<<'\n';return hot>0||cold>0?0:3;}
 double q=ta.budget().joule_J+tb.budget().joule_J,mismatch=q-dt*result.power,thermal_res=ta.budget().residual_J+tb.budget().residual_J;require(std::abs(mismatch)<=5e-10*(std::abs(q)+dt*result.power),"same-state Joule mapping differs between EM and thermal quadrature");require(upper.preflight(ta)&&lower.preflight(tb),"common thermal preflight failed");require(upper.commit(std::move(ta))&&lower.commit(std::move(tb)),"common thermal commit failed");totals.work+=result.work;totals.joule+=q;totals.damping+=result.damping;auto ma=thermal_metrics(upper,material),mb=thermal_metrics(lower,material);double global=totals.work-(result.magnetic-totals.initial_B)-(ma.energy+mb.energy-totals.initial_H)-totals.damping;require(std::abs(global)<=1e-8*(std::abs(totals.work)+std::abs(result.magnetic-totals.initial_B)+totals.joule+totals.damping)+upper.state().cumulative[13]+lower.state().cumulative[13],"cumulative EM+thermal energy failed");step=next;++taken;save(out,step,upper,lower,em,totals,row(step,times[step],currents[step],result,ma,mb,totals,q,thermal_res,mismatch));std::cout<<"step="<<step<<" t_ns="<<times[step]*1e9<<" Tmax="<<std::max(ma.maxT,mb.maxT)<<" phase="<<std::max(ma.max_phase,mb.max_phase)<<" sigma_min="<<result.sigma_min<<" EM_res="<<result.residual<<'\n';}
 if(step+1==int(times.size())){std::ofstream done(out/"DONE.json");done<<"{\"status\":\"completed_supported_solid_only_component\",\"full_plasma_run\":false,\"steps\":"<<step<<"}\n";}std::cout<<"chunk_complete steps="<<taken<<" accepted="<<step<<" wall_s="<<std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
